async function api(path,opts={}){const r=await fetch(path,{headers:{"Content-Type":"application/json"},...opts});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||"Request failed");return d}
async function createAttempt(){try{const d=await api("/api/attempts",{method:"POST",body:JSON.stringify({session_id:state.sessionId,section:$("section").value,difficulty:$("difficulty").value,question_count:Number($("count").value),year_level:Number($("yearLevel").value)})});state.attemptId=d.id}catch(e){console.error(e)}}
async function saveResponse(r){if(!state.attemptId)return;try{await api("/api/responses",{method:"POST",body:JSON.stringify({attempt_id:state.attemptId,session_id:state.sessionId,question_id:r.q.id,section:r.q.section,difficulty:r.q.difficulty,selected_answer:r.selected,correct_answer:r.q.a,is_correct:r.correct,timed_out:r.timeout,response_seconds:Number(r.time.toFixed(3)),question_text:r.q.q,answer_options:r.q.o})})}catch(e){console.error(e)}}
async function finish(){if(!state.attemptId)return;const total=state.results.length,correct=state.results.filter(r=>r.correct).length,t=state.results.filter(r=>r.timeout).length,wrong=total-correct-t,avg=total?state.results.reduce((s,r)=>s+r.time,0)/total:0;try{await api("/api/attempts/"+state.attemptId,{method:"PATCH",body:JSON.stringify({completed_at:new Date().toISOString(),score:Math.round(correct/total*100),correct_count:correct,wrong_count:wrong,timeout_count:t,average_response_seconds:Number(avg.toFixed(3))})})}catch(e){console.error(e)}}
function show(id){["start","quiz","results"].forEach(x=>$(x).classList.toggle("hidden",x!==id))}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
async function start(){clearInterval(state.timer);state.sessionId=crypto.randomUUID();state.attemptId=null;state.results=[];const year=Number($("yearLevel").value);await createAttempt();let p=Q.filter(q=>( $("section").value==="mixed"||q.section===$("section").value )&&( $("difficulty").value==="all"||q.difficulty===$("difficulty").value )&&year>=q.yearMin&&year<=q.yearMax);if(p.length<Number($("count").value))p=Q.filter(q=>( $("section").value==="mixed"||q.section===$("section").value )&&Number($("yearLevel").value)>=q.yearMin&&Number($("yearLevel").value)<=q.yearMax);let fresh=p.filter(q=>!state.lastQuestionIds.includes(q.id));if(fresh.length<Number($("count").value))fresh=p;state.questions=shuffle(fresh).slice(0,Math.min(Number($("count").value),fresh.length));state.lastQuestionIds=state.questions.map(q=>q.id);state.i=0;show("quiz");render()}
function render(){clearInterval(state.timer);const q=state.questions[state.i];state.selected=null;state.submitted=false;state.startedAt=performance.now();state.remaining=q.time;$("sectionLabel").textContent=labels[q.section];$("progress").textContent="Question "+(state.i+1)+" of "+state.questions.length;$("bar").style.width=(state.i/state.questions.length*100)+"%";$("tag").textContent=labels[q.section];$("diff").textContent=q.difficulty;$("question").textContent=q.q;$("passage").textContent=q.passage||"";$("passage").classList.toggle("hidden",!q.passage);$("options").innerHTML="";q.o.forEach((o,i)=>{const b=document.createElement("button");b.className="option";b.innerHTML='<span class="letter">'+String.fromCharCode(65+i)+'</span><span>'+o+'</span>';b.onclick=()=>select(i);$("options").appendChild(b)});$("feedback").className="feedback hidden";$("submit").classList.remove("hidden");$("next").classList.add("hidden");tick();state.timer=setInterval(tick,1000)}
function select(i){if(!state.submitted){state.selected=i;[...$("options").children].forEach((b,j)=>b.classList.toggle("selected",j===i))}}
function tick(){const q=state.questions[state.i],wrap=document.querySelector(".timer");$("timer").textContent=state.remaining;wrap.classList.toggle("warn",state.remaining<=15&&state.remaining>5);wrap.classList.toggle("danger",state.remaining<=5);if(state.remaining<=0)submit(true);else state.remaining--}
async function submit(timeout=false){if(state.submitted)return;state.submitted=true;clearInterval(state.timer);const q=state.questions[state.i],time=Math.min(q.time,Math.max(0,(performance.now()-state.startedAt)/1000)),correct=!timeout&&state.selected===q.a,r={q,selected:state.selected,correct,timeout,time};state.results.push(r);[...$("options").children].forEach((b,j)=>{b.disabled=true;if(j===q.a)b.classList.add("correct");if(state.selected===j&&j!==q.a)b.classList.add("incorrect")});const fb=$("feedback");fb.className="feedback "+(timeout?"timeout":correct?"good":"bad");fb.textContent=timeout?"Time’s up. Correct answer: "+String.fromCharCode(65+q.a)+". "+q.e:correct?"Correct! "+q.e:"Not quite. Correct answer: "+String.fromCharCode(65+q.a)+". "+q.e;$("submit").classList.add("hidden");$("next").classList.remove("hidden");$("next").textContent=state.i===state.questions.length-1?"See Results →":"Next Question →";await saveResponse(r)}
async function next(){if(!state.submitted)return;if(state.i===state.questions.length-1){await finish();results();}else{state.i++;render()}}
function practiceAmount(n){if(n<=0)return {questions:0,minutes:0};if(n===1)return {questions:10,minutes:10};if(n===2)return {questions:15,minutes:15};if(n===3)return {questions:20,minutes:20};return {questions:25,minutes:30}}
function buildPracticeSummary(){const wrong=state.results.filter(r=>!r.correct&&!r.timeout),timed=state.results.filter(r=>r.timeout),bySkill={};wrong.forEach(r=>{const skill=skillMap[r.q.id]||labels[r.q.section];bySkill[skill]??={count:0,section:r.q.section};bySkill[skill].count++});const items=Object.entries(bySkill).sort((a,b)=>b[1].count-a[1].count).slice(0,6).map(([skill,x])=>{const p=practiceAmount(x.count);return '<div class="practice-item"><div><strong>'+skill+'</strong><span>'+labels[x.section]+'</span></div><b>'+p.questions+' questions</b><em>about '+p.minutes+' min</em></div>'}).join("");const timeoutText=timed.length?'<p class="practice-note">'+timed.length+' timed-out question'+(timed.length===1?' was':'s were')+' also recorded. Add <strong>'+Math.max(10,timed.length*5)+' speed-practice questions</strong> and focus on answering steadily without spending too long on one problem.</p>':"";if(!items&&!timed.length)return '<div class="practice-empty"><strong>Great job!</strong><p>No clear weak area was identified from this attempt. Keep a maintenance routine of <strong>10 mixed questions per week</strong>.</p></div>';return '<p class="practice-intro">Based on the questions you missed, these are the areas to practise next. The amount increases when you miss more questions in the same skill.</p><div class="practice-list">'+items+'</div>'+timeoutText}
function results(){const total=state.results.length,c=state.results.filter(r=>r.correct).length,t=state.results.filter(r=>r.timeout).length,w=total-c-t,score=Math.round(c/total*100),avg=state.results.reduce((s,r)=>s+r.time,0)/total;show("results");$("score").textContent=score+"%";document.querySelector(".score").style.setProperty("--score",score+"%");$("correct").textContent=c;$("wrong").textContent=w;$("timeouts").textContent=t;$("avg").textContent=avg.toFixed(1)+"s";$("resultTitle").textContent=score>=80?"Excellent work!":score>=60?"Good progress — keep practising!":"Keep going — speed and accuracy will improve.";const by={};state.results.forEach(r=>{by[r.q.section]??={c:0,n:0,t:0};by[r.q.section].n++;by[r.q.section].c+=r.correct?1:0;by[r.q.section].t+=r.time});$("breakdown").innerHTML=Object.entries(by).map(([s,x])=>'<div class="row"><span>'+labels[s]+'</span><b>'+x.c+'/'+x.n+'</b><b>'+(x.t/x.n).toFixed(1)+'s avg</b></div>').join("");$("practiceSummary").innerHTML=buildPracticeSummary()}

